(()=>{
const notebookStyles=document.createElement('link');notebookStyles.rel='stylesheet';notebookStyles.href='notebook.css';document.head.append(notebookStyles);
const rhythmStyles=document.createElement('link');rhythmStyles.rel='stylesheet';rhythmStyles.href='alternating.css';document.head.append(rhythmStyles);
const $=id=>document.getElementById(id),make=(tag,cls,text)=>{const item=document.createElement(tag);if(cls)item.className=cls;if(text)item.textContent=text;return item};
const header=document.querySelector('header'),main=document.querySelector('main'),aside=main.querySelector('aside'),waiting=$('waiting'),controls=$('controls'),log=$('evolutionLog'),results=$('results'),start=$('start'),cancel=$('cancel');
const stages=[
  {id:'exploreStage',name:'Explore',title:'Play with the field'},
  {id:'evolveStage',name:'Evolve',title:'Search for a quieter field'},
  {id:'examineStage',name:'Examine',title:'Inspect the best result'}
];
function go(index){document.getElementById(stages[index].id).scrollIntoView({behavior:'instant',block:'start'})}
function navigation(current,position){const nav=make('nav','stageNavigation '+position);nav.setAttribute('aria-label','Notebook stages');stages.forEach((stage,index)=>{const link=make('button','stageTab',String(index+1).padStart(2,'0')+' '+stage.name);link.type='button';link.dataset.stage=String(index);link.setAttribute('aria-current',index===current?'step':'false');link.onclick=()=>go(index);nav.append(link)});return nav}
function section(index,kicker,description){const root=make('section','notebookStage stage-'+stages[index].name.toLowerCase());root.id=stages[index].id;root.setAttribute('aria-labelledby',root.id+'Title');root.append(navigation(index,'top'));const intro=make('div','stageIntro');const eyebrow=make('span','stageKicker',kicker);const title=make('h2','',stages[index].title);title.id=root.id+'Title';const copy=make('p','',description);intro.append(eyebrow,title,copy);root.append(intro);return root}
const explore=section(0,'01 · THE PLAYGROUND','Paint Arc A, Arc B, or Cross tiles and send particles through your field. Collisions can rewire a tile, changing the route the next particle sees.');
const evolve=section(1,'02 · THE SEARCH','Every candidate gets the same seeded traffic. Follow the live fitness landscape as layouts compete. Your edited playground stays independent from a fresh search.');
const examine=section(2,'03 · THE RESULT','Reveal the best field when you are ready. Inspect its collision score, then replay the same seeded traffic to see how the layout behaves.');
const headerNav=navigation(0,'header');headerNav.classList.add('notebookHeaderNav');header.append(headerNav);

const playLayout=make('div','playLayout'),playTools=make('div','playTools'),playBoard=make('div','playBoard');
const palette=make('div','tilePalette');palette.setAttribute('role','group');palette.setAttribute('aria-label','Tile to paint');
const tileNames=['Arc A','Arc B','Cross'],tileNotes=['North-east / south-west','North-west / south-east','Straight paths'];let selectedTile=0;
tileNames.forEach((name,index)=>{const choice=make('button','tileChoice tile-'+index,name);choice.type='button';choice.setAttribute('aria-label',name+' tile, '+tileNotes[index]);choice.setAttribute('aria-pressed',String(index===selectedTile));choice.onclick=()=>{selectedTile=index;palette.querySelectorAll('button').forEach((button,i)=>button.setAttribute('aria-pressed',String(i===index)))};palette.append(choice)});
const boardSizeLabel=make('label','fieldSelectLabel','Field size'),boardSize=make('select','fieldSelect');boardSize.id='sandboxSize';[['12,9','12 × 9'],['16,12','16 × 12'],['24,18','24 × 18']].forEach(([value,label])=>{const option=make('option','',label);option.value=value;boardSize.append(option)});boardSizeLabel.append(boardSize);
const fluxLabel=make('label','rangeLabel','Particle rate'),fluxValue=make('output','','6 / s'),flux=make('input','sandboxRange');flux.type='range';flux.min='2';flux.max='12';flux.value='6';fluxLabel.append(fluxValue,flux);
const speedLabel=make('label','rangeLabel','Particle speed'),speedValue=make('output','','3 tiles / s'),speed=make('input','sandboxRange');speed.type='range';speed.min='1';speed.max='6';speed.value='3';speedLabel.append(speedValue,speed);
const playActions=make('div','playActions'),runTraffic=make('button','primaryAction','Run particle trial'),newField=make('button','quietAction','New random field');runTraffic.id='runTraffic';newField.id='newSandboxField';runTraffic.type=newField.type='button';playActions.append(runTraffic,newField);
const sandboxStatus=make('p','sandboxStatus','Select a tile and click or tap a cell to paint it.');sandboxStatus.setAttribute('role','status');sandboxStatus.setAttribute('aria-live','polite');
const sandboxStats=make('dl','sandboxStats');sandboxStats.setAttribute('aria-label','Particle trial results');[['sandboxCollisions','0','Collisions'],['sandboxExits','0','Particles exited'],['sandboxClock','0.0 s','Trial time']].forEach(([id,value,label])=>{const group=make('div','sandboxStat'),number=make('dd','',value),caption=make('dt','',label);number.id=id;group.append(number,caption);sandboxStats.append(group)});
playTools.append(make('h3','','Choose a route'),palette,boardSizeLabel,fluxLabel,speedLabel,playActions,sandboxStatus,sandboxStats);
const sandboxFrame=make('div','sandboxFrame'),sandboxCanvas=make('canvas','sandboxCanvas');sandboxCanvas.id='sandboxCanvas';sandboxCanvas.tabIndex=0;sandboxCanvas.setAttribute('aria-label','Editable tile field. Paint a cell with the selected tile.');sandboxFrame.append(sandboxCanvas);playBoard.append(sandboxFrame,make('p','boardHint','Tap or click a cell to replace its tile. Change the field while traffic is running to alter the routes.'));playLayout.append(playTools,playBoard);explore.append(playLayout,navigation(0,'bottom'));

const settings=make('details','evolveSettings'),settingsSummary=make('summary','','Search settings · defaults are ready');settings.append(settingsSummary,controls);
const evolveActions=make('div','evolveActions');evolveActions.append(start,cancel);
const examineBest=make('button','examineAction','Examine best field →'),examineBestBottom=make('button','examineAction','Examine best field →');examineBest.type=examineBestBottom.type='button';examineBest.disabled=examineBestBottom.disabled=true;
const resultsNote=make('p','winnerGate','The winning field stays hidden until you choose Examine.');resultsNote.id='winnerGate';resultsNote.setAttribute('role','status');
const resultPlaceholder=make('div','resultPlaceholder','After a search finishes, examine the winner here.');resultPlaceholder.id='resultPlaceholder';
const evolveMeta=make('div','evolveMeta');evolveMeta.append(settings,evolveActions,waiting,log,examineBest,navigation(1,'bottom'));evolve.append(evolveMeta);
const examineBody=make('div','examineBody');examineBody.append(resultsNote,resultPlaceholder,examineBestBottom,results);examine.append(examineBody,navigation(2,'bottom'));
aside.remove();main.replaceChildren(explore,evolve,examine);main.querySelectorAll('.stageNavigation').forEach(nav=>nav.remove());const footerNav=navigation(0,'footer');footerNav.classList.add('notebookFooterNav');main.append(footerNav);

const sandboxConfig={cols:12,rows:9,seed:'arcfield-playground',duration:12,flux:6,speed:3};let sandboxTiles=new Uint8Array(sandboxConfig.cols*sandboxConfig.rows),sandboxEngine=null,sandboxSim=null,sandboxPlaying=false,sandboxLoading=false,sandboxLast=0,sandboxAccum=0;
function randomizeBoard(){for(let y=0;y<sandboxConfig.rows;y++)for(let x=0;x<sandboxConfig.cols;x++)sandboxTiles[y*sandboxConfig.cols+x]=Math.floor(Math.random()*3);sandboxSim=null;sandboxPlaying=false;drawSandbox();sandboxStatus.textContent='New field ready. Select a tile, then paint or run the traffic.';runTraffic.textContent='Run particle trial';}
function drawSandbox(){const width=sandboxCanvas.getBoundingClientRect().width;if(width<2)return;const d=window.devicePixelRatio||1,height=width*sandboxConfig.rows/sandboxConfig.cols;sandboxCanvas.width=Math.round(width*d);sandboxCanvas.height=Math.round(height*d);const ctx=sandboxCanvas.getContext('2d'),size=width/sandboxConfig.cols;ctx.setTransform(d,0,0,d,0,0);ctx.fillStyle='#13211b';ctx.fillRect(0,0,width,height);ctx.lineWidth=Math.max(1.5,size*.065);const tiles=sandboxSim?sandboxSim.tiles:sandboxTiles;for(let y=0;y<sandboxConfig.rows;y++)for(let x=0;x<sandboxConfig.cols;x++){const type=tiles[y*sandboxConfig.cols+x],px=x*size,py=y*size;ctx.strokeStyle=['#a7d883','#72c6b3','#e6a46c'][type];ctx.beginPath();if(type===0){ctx.arc(px+size,py,size/2,Math.PI/2,Math.PI);ctx.moveTo(px+size/2,py+size);ctx.arc(px,py+size,size/2,0,-Math.PI/2,true)}else if(type===1){ctx.arc(px,py,size/2,0,Math.PI/2);ctx.moveTo(px+size/2,py+size);ctx.arc(px+size,py+size,size/2,Math.PI,Math.PI*1.5)}else{ctx.moveTo(px+size/2,py);ctx.lineTo(px+size/2,py+size);ctx.moveTo(px,py+size/2);ctx.lineTo(px+size,py+size/2)}ctx.stroke();ctx.strokeStyle='#ffffff18';ctx.lineWidth=1;ctx.strokeRect(px,py,size,size)}if(sandboxSim){for(const particle of sandboxSim.particles){ctx.fillStyle='#fff5d9';ctx.shadowBlur=9;ctx.shadowColor='#fff0c4';ctx.beginPath();ctx.arc(particle.px*size,particle.py*size,Math.max(2,size*.11),0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}for(const spark of sandboxSim.sparks){ctx.strokeStyle=`rgba(255,174,105,${spark.life/.35})`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(spark.x*size,spark.y*size,(1-spark.life/.35)*size*.65+2,0,Math.PI*2);ctx.stroke()}}}
function updateSandboxStats(){if(!sandboxSim)return;$('sandboxCollisions').textContent=String(sandboxSim.collisions);$('sandboxExits').textContent=String(sandboxSim.exits);$('sandboxClock').textContent=sandboxSim.time.toFixed(1)+' s'}
sandboxCanvas.onclick=event=>{const rect=sandboxCanvas.getBoundingClientRect(),x=Math.floor((event.clientX-rect.left)/rect.width*sandboxConfig.cols),y=Math.floor((event.clientY-rect.top)/rect.height*sandboxConfig.rows);if(x<0||y<0||x>=sandboxConfig.cols||y>=sandboxConfig.rows)return;const index=y*sandboxConfig.cols+x;sandboxTiles[index]=selectedTile;if(sandboxSim){sandboxSim.tiles[index]=selectedTile;sandboxSim.lastTiles[index]=selectedTile}drawSandbox();sandboxStatus.textContent='Tile changed. Run or resume traffic to see its effect.'};
boardSize.onchange=()=>{[sandboxConfig.cols,sandboxConfig.rows]=boardSize.value.split(',').map(Number);sandboxTiles=new Uint8Array(sandboxConfig.cols*sandboxConfig.rows);randomizeBoard()};flux.oninput=()=>{sandboxConfig.flux=Number(flux.value);fluxValue.textContent=flux.value+' / s'};speed.oninput=()=>{sandboxConfig.speed=Number(speed.value);speedValue.textContent=speed.value+' tiles / s'};newField.onclick=randomizeBoard;
runTraffic.onclick=async()=>{if(sandboxLoading)return;if(sandboxPlaying){sandboxPlaying=false;runTraffic.textContent='Resume traffic';sandboxStatus.textContent='Traffic paused. Paint tiles or resume the same trial.';return}try{sandboxLoading=true;runTraffic.disabled=true;if(!sandboxEngine)sandboxEngine=await createCompactEngine();if(!sandboxSim||sandboxSim.time>=sandboxConfig.duration){const config={...sandboxConfig};sandboxSim=sandboxEngine.createSim(Uint8Array.from(sandboxTiles),config,scenario(config));updateSandboxStats()}sandboxPlaying=true;sandboxLast=0;sandboxAccum=0;runTraffic.textContent='Pause traffic';sandboxStatus.textContent='Particles are following the shared routes. Collisions can rewire a tile.'}catch(error){sandboxStatus.textContent='Could not start the particle trial: '+error.message}finally{sandboxLoading=false;runTraffic.disabled=false}};
function animateSandbox(now){if(sandboxPlaying&&sandboxSim){if(sandboxLast)sandboxAccum+=Math.min(.1,(now-sandboxLast)/1000);sandboxLast=now;while(sandboxAccum>=1/60&&sandboxSim.time<sandboxConfig.duration-1e-7){sandboxEngine.tick(sandboxSim);sandboxAccum-=1/60}drawSandbox();updateSandboxStats();if(sandboxSim.time>=sandboxConfig.duration-1e-7){sandboxPlaying=false;runTraffic.textContent='Run trial again';sandboxStatus.textContent='Trial complete. Paint the field or run the same traffic again.'}}requestAnimationFrame(animateSandbox)}
randomizeBoard();requestAnimationFrame(animateSandbox);new ResizeObserver(drawSandbox).observe(sandboxCanvas);

const replayWinner=replay;let winnerRevealed=false,winnerReady=false;
replay=async()=>{if(winnerRevealed)return replayWinner()};$('replay').onclick=()=>replayWinner();
function showWinner(){if(!winnerReady||!winner)return;winnerRevealed=true;results.hidden=false;resultPlaceholder.hidden=true;resultsNote.hidden=true;replayWinner();go(2)}
examineBest.onclick=examineBestBottom.onclick=showWinner;
function syncWinner(){if(winner&&!results.hidden){winnerReady=true;examineBest.disabled=examineBestBottom.disabled=false;resultsNote.textContent='Your best field is ready. Choose Examine to reveal it.';if(!winnerRevealed)results.hidden=true}else if(!winnerReady){examineBest.disabled=examineBestBottom.disabled=true}if(!winnerRevealed){resultsNote.hidden=false;resultPlaceholder.hidden=false}evolveActions.append(start,cancel);start.textContent=winnerReady?'Evolve another field':'Start fresh evolution';if(winnerReady){$('waiting').querySelector('#message').textContent='Search complete. Explore the graph, then choose Examine when you are ready.';}}
new MutationObserver(syncWinner).observe(results,{attributes:true,attributeFilter:['hidden']});
const appStart=start.onclick;start.textContent='Start fresh evolution';$('message').textContent='Start with the shared defaults, or expand search settings to tune this run.';start.onclick=()=>{const previousWorker=worker;const result=appStart();evolveActions.append(start,cancel);if(worker&&worker!==previousWorker){winnerReady=false;winnerRevealed=false;examineBest.disabled=examineBestBottom.disabled=true;resultsNote.hidden=false;resultsNote.textContent='The winning field stays hidden until you choose Examine.';resultPlaceholder.hidden=false;results.hidden=true}start.textContent=winnerReady?'Evolve another field':'Start fresh evolution';return result};
const waitingTitle=waiting.querySelector('h3');if(waitingTitle)waitingTitle.textContent='The search is under way.';const waitingCopy=waiting.querySelector('p');if(waitingCopy)waitingCopy.textContent='Each generation tests fields against the same particle traffic. The graphs update as candidates finish.';
log.hidden=false;resetLandscape({...sandboxConfig,cols:16,rows:12,generations:Number($('generations').value)});drawEvolution();
const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){const index=stages.findIndex(stage=>stage.id===entry.target.id);document.querySelectorAll('.stageNavigation [data-stage]').forEach((button,i)=>button.setAttribute('aria-current',i===index?'step':'false'))}},{rootMargin:'-20% 0px -65%'});stages.forEach(stage=>observer.observe(document.getElementById(stage.id)));
requestAnimationFrame(()=>drawSandbox());
})();